public class Namensschild {

    public static void main(String[] args) {
        String name = "  lisa Mustermann ";

        String sauber = name.trim();
        String gross = sauber.toUpperCase();
        String anrede = "Frau " + gross.charAt(0) + ".";

        System.out.println("Sauber: " + sauber);
        System.out.println("Gross: " + gross);
        System.out.println("Anrede: " + anrede);
        System.out.println("Zeichenanzahl: " + sauber.length());
    }
}

